-- /* ---- ✴️ Variables ✴️ ---- */  #
-- Generated by hyprlang2lua and reviewed for Hyprland 0.56.

local defaults = require("UserConfigs/defaults")
local mainMod = defaults.user_main_mod
local scriptsDir = defaults.scripts_dir
local UserScripts = defaults.user_scripts_dir
local UserConfigs = defaults.user_configs_dir
local hyprsplit = require("hyprsplit")

hyprsplit.config({ num_workspaces = 10 })

--  IMPORTANT: If you want to remap and existing keybind you MUST unbindd it first

-- The bindings are CASE SENSITIVE. We suggest you copy the exisitng binding here
--  Then change `bindd` to `unbind`

-- E.g.
-- unbind = $mainMod, Return, Open terminal, exec, $term
-- bindd = $mainMod, Return, Open terminal, exec, ghostty
--
-- unbind = $mainMod, E, file manager, exec, $files
-- bindd = $mainMod, T, file manager, exec, $files

-- If you are ADDING a bindd, make sure you include the description
-- Other the keybind search menu might not show it properly

-- E.g.
-- bindd = $mainMod, Z, My z app, exec APPNAME

-- For passthrough keyboard into a VM
-- bind = $mainMod ALT, P, submap, passthru
--submap = passthru
-- to unbind
--bind = $mainMod ALT, P, submap, reset
--submap = reset

-- Vim-style window focus (Alt + h/j/k/l)
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))

-- Move windows (Alt + Shift + h/j/k/l)
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "left", once = true }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + RETURN", hl.dsp.window.move({ direction = "right" }))

-- Window operations
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd("hyprctl reload"))
hl.bind(mainMod .. " + T", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen_state({ internal = 1, client = -1, action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

-- Monitor-local workspaces (Alt + 1-0, Alt + Shift + 1-0).
for workspace = 1, 10 do
    local key = tostring(workspace % 10)
    hl.bind(mainMod .. " + " .. key, hyprsplit.dsp.focus({ workspace = workspace }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hyprsplit.dsp.window.move({
        workspace = workspace,
        follow = true,
    }))
end

-- Special workspace
hl.bind(mainMod .. " + SHIFT + U", hl.dsp.window.move({ workspace = "special" }), { description = "move to special workspace" })
hl.bind(mainMod .. " + U", hl.dsp.workspace.toggle_special(""), { description = "toggle special workspace" })

-- Layouts (Alt + Shift + ,/.)
hl.bind(mainMod .. " + SHIFT + COMMA", hl.dsp.layout("switch, bsp"))
hl.bind(mainMod .. " + SHIFT + PERIOD", hl.dsp.layout("switch, grid"))

-- Resize (Alt + oem_plus/oem_minus)
hl.bind(mainMod .. " + EQUAL", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = math.floor(w.size.x * -10 / 100), y = 0, relative = true })) end)
hl.bind(mainMod .. " + MINUS", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = math.floor(w.size.x * 10 / 100), y = 0, relative = true })) end)
hl.bind(mainMod .. " + SHIFT + EQUAL", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = 0, y = math.floor(w.size.y * -10 / 100), relative = true })) end)
hl.bind(mainMod .. " + SHIFT + MINUS", function() local w = hl.get_active_window(); if not w then return end; hl.dispatch(hl.dsp.window.resize({ x = 0, y = math.floor(w.size.y * 10 / 100), relative = true })) end)

--# Rofi
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("rofi -show drun"))

-- Reload
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("hyprctl reload"))

